<script setup lang="ts">
import { reactive,ref } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus';import { ElMessage } from '@/app/messages'
import AsyncState from '@/components/AsyncState.vue'
import { adminQuestions,newQuestionVersion,putProblemOnline,takeProblemOffline } from '@/api/question'
import { readableError } from '@/api/errors'
import type { AdminProblemSummary,ProblemLifecycleStatus } from '@/api/types'

const router=useRouter(),page=ref(1)
const searchText=ref('')
const filters=reactive<{title:string;problemNo:string;status:''|ProblemLifecycleStatus}>({title:'',problemNo:'',status:''})
const query=useQuery({queryKey:['admin','problems',page,filters],queryFn:()=>adminQuestions({current:page.value,pageSize:20,title:filters.title.trim()||undefined,problemNo:filters.problemNo?Number(filters.problemNo):undefined,status:filters.status||undefined})})
function search(){const text=searchText.value.trim();filters.problemNo=/^\d+$/.test(text)?text:'';filters.title=filters.problemNo?'':text;page.value=1;void query.refetch()}
async function createVersion(row:AdminProblemSummary){if(!row.currentQuestionId||row.currentRowVersion===null)return;try{const id=await newQuestionVersion(row.currentQuestionId,row.currentRowVersion);ElMessage.success({ message: '已创建新版本草稿' });await router.push(`/admin/problems/${id}/edit`)}catch(e){ElMessage.error({ message: readableError(e) });void query.refetch()}}
async function offline(row:AdminProblemSummary){try{const result=await ElMessageBox.prompt('请输入下线原因。下线后用户不能看到或提交该题，历史提交仍保留。','下线题目',{confirmButtonText:'确认下线',cancelButtonText:'取消',inputType:'textarea',inputValidator:v=>Boolean(v.trim())||'请填写下线原因'});await takeProblemOffline(row.problemNo,row.lifecycleVersion,result.value.trim());ElMessage.success({ message: `题目 ${row.problemNo} 已下线` });await query.refetch()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error({ message: readableError(e) })}}
async function online(row:AdminProblemSummary){try{await ElMessageBox.confirm(`确认重新上线题目 ${row.problemNo}？`,'重新上线',{type:'warning'});await putProblemOnline(row.problemNo,row.lifecycleVersion);ElMessage.success({ message: '题目已重新上线' });await query.refetch()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error({ message: readableError(e) })}}
const statusLabel:Record<ProblemLifecycleStatus,string>={DRAFT:'草稿',ONLINE:'已上线',OFFLINE:'已下线'}
</script>
<template><div class="page admin-page">
  <div class="page-head"><div><h1 class="page-title">题目管理</h1><p class="page-lead">维护题目草稿、版本和上下线状态</p></div><el-button class="new-problem" type="primary" @click="$router.push('/admin/problems/new')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg>新建题目</el-button></div>
  <section class="surface filters"><el-input v-model="searchText" placeholder="搜索题号或标题…" aria-label="搜索题号或标题" clearable @keyup.enter="search" @clear="search"><template #prefix><svg class="search-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg></template></el-input><el-select v-model="filters.status" placeholder="全部状态" aria-label="题目状态" clearable><el-option label="草稿" value="DRAFT"/><el-option label="已上线" value="ONLINE"/><el-option label="已下线" value="OFFLINE"/></el-select><el-button type="primary" @click="search">查询</el-button></section>
  <section class="surface table-shell"><AsyncState :loading="query.isPending.value" :error="query.isError.value?readableError(query.error.value):undefined" :empty="query.data.value?.records.length===0" @retry="query.refetch()"><el-table :data="query.data.value?.records" stripe>
    <el-table-column label="题号" prop="problemNo" width="86"/><el-table-column label="题目" prop="title" min-width="230"/><el-table-column label="当前版本" width="110"><template #default="{row}">{{row.currentVersion?`v${row.currentVersion}`:'—'}}</template></el-table-column>
    <el-table-column label="状态" width="110"><template #default="{row}"><el-tag class="lifecycle-tag" :class="`lifecycle-${row.status.toLowerCase()}`">{{statusLabel[row.status as ProblemLifecycleStatus]}}</el-tag></template></el-table-column>
    <el-table-column label="草稿" width="110"><template #default="{row}"><el-tag v-if="row.draftId" class="draft-tag">v{{row.draftVersion}}</el-tag><span v-else class="muted">—</span></template></el-table-column>
    <el-table-column label="操作" min-width="310" fixed="right"><template #default="{row}"><div class="problem-actions"><el-button v-if="row.draftId" link type="primary" @click="$router.push(`/admin/problems/${row.draftId}/edit`)">编辑草稿</el-button><el-button v-else-if="row.currentQuestionId" link type="primary" @click="$router.push(`/admin/problems/${row.currentQuestionId}/edit`)">查看版本</el-button><el-button v-else link type="primary" @click="$router.push(`/admin/problems/${row.rootQuestionId}/edit`)">编辑草稿</el-button><el-button v-if="row.currentQuestionId&&!row.draftId" link type="primary" @click="createVersion(row)">创建新版本</el-button><el-button v-if="row.status==='ONLINE'" link type="danger" @click="offline(row)">下线</el-button><el-button v-if="row.status==='OFFLINE'" link type="success" @click="online(row)">重新上线</el-button></div></template></el-table-column>
  </el-table></AsyncState></section>
  <div v-if="query.data.value" class="pager"><el-pagination v-model:current-page="page" :page-size="20" :total="query.data.value.total" layout="total,prev,pager,next" @current-change="query.refetch()"/></div>
</div></template>
<style scoped>
.admin-page{max-width:1240px;padding-top:32px}.page-head{align-items:center;margin-bottom:22px}.page-title{font-size:26px;color:#f1f5ff;letter-spacing:-.02em}.page-lead{font-size:12px;margin-top:8px;color:#97a6bf}
.new-problem{height:36px;padding:0 18px;border-radius:9px}.new-problem svg{width:17px;height:17px;margin-right:8px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round}
.filters{display:grid;grid-template-columns:minmax(180px,1fr) 156px auto;gap:10px;padding:10px;margin-bottom:14px;border-radius:12px}.filters :deep(.el-input__wrapper),.filters :deep(.el-select__wrapper){min-height:36px;border-radius:8px;background:linear-gradient(110deg,#202837,#1b2331)!important}.filters :deep(.el-input__inner){font-size:12px}.filters :deep(.el-select__placeholder){font-size:12px}.filters>.el-button{height:36px;min-width:64px;border-radius:8px}.search-icon{width:17px;height:17px;fill:none;stroke:#9aafcf;stroke-width:1.7;stroke-linecap:round;margin-right:4px}
.table-shell{overflow:hidden;border-radius:12px}.table-shell :deep(.el-table__cell){padding:10px 0}.table-shell :deep(.cell){font-size:12px;line-height:20px}.table-shell :deep(th.el-table__cell){padding:11px 0;font-weight:600}.table-shell :deep(.el-table__cell:first-child .cell){padding-left:20px}.table-shell :deep(.el-table__cell:last-child .cell){padding-right:20px}.table-shell :deep(.el-table__inner-wrapper::before){display:none}
.lifecycle-tag,.draft-tag{height:23px;padding:0 9px;border-radius:7px;font-size:11px;--el-tag-bg-color:rgba(143,157,190,.12);--el-tag-border-color:rgba(143,157,190,.19);--el-tag-text-color:#bcc8e1}.lifecycle-online{--el-tag-bg-color:rgba(75,155,111,.23);--el-tag-border-color:rgba(108,185,138,.25);--el-tag-text-color:#a8e6bd}.lifecycle-offline{--el-tag-bg-color:rgba(195,81,98,.15);--el-tag-border-color:rgba(220,111,128,.23);--el-tag-text-color:#f49aa8}.lifecycle-draft,.draft-tag{--el-tag-bg-color:rgba(197,157,72,.15);--el-tag-border-color:rgba(211,174,86,.23);--el-tag-text-color:#eaca86}
.problem-actions{display:flex;align-items:center;gap:18px;white-space:nowrap}.problem-actions :deep(.el-button){margin-left:0;font-size:12px}.pager{display:flex;justify-content:flex-end;margin-top:20px}
@media(max-width:760px){.filters{grid-template-columns:minmax(0,1fr) auto}.filters>:first-child{grid-column:span 2}.page-head{flex-direction:row;align-items:center}.page-title{font-size:23px}.page-lead{max-width:210px;line-height:1.6}.new-problem{padding:0 12px}.admin-page{padding-top:24px}.pager :deep(.el-pagination){flex-wrap:wrap;justify-content:flex-end;gap:6px}.table-shell :deep(.el-table-fixed-column--right){position:relative!important;right:auto!important}.table-shell :deep(.el-table-fixed-column--right::before){display:none}}
</style>
